"""NSE ingestion. Two entryways per dataset: network fetch, or bytes (generated by data/inbox/ manual import)."""
from __future__ import annotations

import csv
import hashlib
import io
import logging
from datetime import date, datetime, timedelta

import requests

from app import db
from app.config import endpoints, settings
from ingest import http
from ingest.http import bootstrap_nse_session, fetch_json
from ingest.udiff import parse_udiff, read_bhav_bytes

log = logging.getLogger(__name__)

_API_DATE_FMT = "%d-%m-%Y"
_FILE_DATE_FMT = "%d-%b-%Y"


# ------------------------------------------------------------------ helpers

def _archives(pattern: str, d: date) -> str:
    return pattern.format(yyyymmdd=d.strftime("%Y%m%d"))


def _mark_bytes(con, source: str, url: str, payload: bytes, rows: int, saved_path: str | None):
    db.upsert_rows(con, "raw_files", [{
        "sha256": hashlib.sha256(payload).hexdigest(),
        "source": source,
        "url": url or "(no url - bytes payload)",
        "saved_path": saved_path or "n/a",
        "bytes": len(payload),
        "rows": rows,
        "http_code": 0 if saved_path is None else None,
        "notes": "manual byte import" if saved_path is None else "",
    }], keys=["sha256"])


# ------------------------------------------------------------------ CM bhavcopy

def cm_bhav_from_bytes(con, payload: bytes, d: date, url: str = "") -> dict:
    parsed = parse_udiff(payload, source="NSE",
                         series_keep=settings()["ingest"]["series_equity_nse"])
    n = db.upsert_rows(con, "px_daily", parsed["px_rows"], keys=["source", "symbol", "date", "series"])
    return {"status": "ok", "date": str(d), "rows": n, "series_kept": "EQ"}


def sync_cm_bhavcopy(con, d: date) -> dict:
    ep = endpoints()["sources"]["nse_cm_bhavcopy"]
    url = _archives(ep["url_pattern"], d)
    r = http.fetch(url, source="nse", save_name=f"BhavCopy_NSE_CM_{d.strftime('%y%m%d')}.zip")
    if not r.ok():
        return {"status": "skip", "date": str(d), "message": f"no file ({r.error})"}
    res = cm_bhav_from_bytes(con, r.bytes, d, url)
    _mark_bytes(con, "NSE", url, r.bytes, res.get("rows", 0), str(r.saved_path))
    res["raw"] = str(r.saved_path)
    return res


def sync_cm_bhavcopy_from_bytes(con, payload: bytes, d: date) -> dict:
    """Manual-import entryway used by ingest/inbox.py for a dropped CM bhavcopy."""
    res = cm_bhav_from_bytes(con, payload, d)
    _mark_bytes(con, "NSE", "(manual CM bhavcopy)", payload, res.get("rows", 0), None)
    return res


# ------------------------------------------------------------------ FO bhavcopy

def fo_bhav_from_bytes(con, payload: bytes, d: date, url: str = "") -> dict:
    parsed = parse_udiff(payload, source="NSE", fo_mode=True)
    rows = parsed["fno_rows"]
    # option_type and strike are part of the PK (NOT NULL in DuckDB): futures persist with '' and 0.0
    for r in rows:
        if not r.get("option_type"):
            r["option_type"] = ""
        if r.get("strike") is None:
            r["strike"] = 0.0
    n = db.upsert_rows(con, "fno_daily", rows,
                       keys=["source", "underlying", "expiry", "instrument", "option_type", "strike", "date"])
    return {"status": "ok", "date": str(d), "rows": n}


def sync_fo_bhavcopy(con, d: date) -> dict:
    ep = endpoints()["sources"]["nse_fo_bhavcopy"]
    url = _archives(ep["url_pattern"], d)
    r = http.fetch(url, source="nse", save_name=f"BhavCopy_NSE_FO_{d.strftime('%y%m%d')}.zip")
    if not r.ok():
        return {"status": "skip", "date": str(d), "message": f"no file ({r.error})"}
    res = fo_bhav_from_bytes(con, r.bytes, d, url)
    _mark_bytes(con, "NSE", url, r.bytes, res.get("rows", 0), str(r.saved_path))
    res["raw"] = str(r.saved_path)
    return res


def sync_fo_bhavcopy_from_bytes(con, payload: bytes, d: date) -> dict:
    """Manual-import entryway used by ingest/inbox.py for a dropped FO bhavcopy."""
    res = fo_bhav_from_bytes(con, payload, d)
    _mark_bytes(con, "NSE", "(manual FO bhavcopy)", payload, res.get("rows", 0), None)
    return res


# ------------------------------------------------------------------ masters

def _parse_equity_master(payload: bytes) -> list[dict]:
    rows = list(csv.reader(io.StringIO(payload.decode("utf-8", "replace"))))
    header = [h.strip().upper() for h in rows[0]]
    col = {c: i for i, c in enumerate(header)}
    i_sym, i_name = col["SYMBOL"], col["NAME OF COMPANY"]
    i_series, i_listing = col["SERIES"], col["DATE OF LISTING"]
    i_paid, i_lot = col["PAID UP VALUE"], col["MARKET LOT"]
    i_isin, i_fv = col["ISIN NUMBER"], col["FACE VALUE"]
    out = []
    for row in rows[1:]:
        if len(row) < len(header) or not row[i_sym].strip():
            continue
        isin = row[i_isin].strip()
        listing = None
        try:
            listing = datetime.strptime(row[i_listing].strip(), _FILE_DATE_FMT).date()
        except ValueError:
            pass
        sym = row[i_sym].strip()
        out.append({
            "security_id": isin if isin else f"NSE:{sym}",
            "isin": isin or None,
            "nse_symbol": sym,
            "name": row[i_name].strip(),
            "nse_series": row[i_series].strip(),
            "listing_date": listing,
            "face_value": _f(row[i_fv]),
            "paid_up_value": _f(row[i_paid]),
            "market_lot": int(float(row[i_lot])) if row[i_lot].strip() else None,
            "listing_status": "listed",
        })
    return out


def _f(v: str):
    v = (v or "").strip()
    if not v:
        return None
    try:
        return float(v)
    except ValueError:
        return None


def sync_equity_master(con) -> dict:
    ep = endpoints()["sources"]["nse_equity_master"]
    r = http.fetch(ep["url"], source="nse", save_name="EQUITY_L.csv")
    if not r.ok():
        return {"status": "fail", "message": f"EQUITY_L.csv {r.error}"}
    out = _parse_equity_master(r.bytes)
    n = db.upsert_rows(con, "ref_security", out, keys=["security_id"])
    _mark_bytes(con, "NSE", ep["url"], r.bytes, n, str(r.saved_path))
    return {"status": "ok", "rows": n}


def sync_equity_master_from_bytes(con, payload: bytes) -> dict:
    out = _parse_equity_master(payload)
    n = db.upsert_rows(con, "ref_security", out, keys=["security_id"])
    _mark_bytes(con, "NSE", "(manual EQUITY_L.csv)", payload, n, None)
    return {"status": "ok", "rows": n}


def _parse_etf_master(payload: bytes) -> list[dict]:
    rows = list(csv.reader(io.StringIO(payload.decode("utf-8", "replace"))))
    header = [h.strip().upper() for h in rows[0]]
    i_sym = header.index("SYMBOL") if "SYMBOL" in header else 0
    i_name = header.index("NAME") if "NAME" in header else 1
    i_isin = header.index("ISIN") if "ISIN" in header else (5 if len(header) > 5 else None)
    out = []
    for row in rows[1:]:
        if len(row) < 2 or not row[i_sym].strip():
            continue
        sym = row[i_sym].strip()
        isin = row[i_isin].strip() if i_isin is not None and len(row) > i_isin else ""
        out.append({
            "security_id": isin if isin else f"NSE:{sym}",
            "isin": isin or None,
            "nse_symbol": sym,
            "name": row[i_name].strip() if len(row) > i_name else sym,
            "is_etf": True,
            "listing_status": "listed",
        })
    return out


