# ------------------------------------------------------------------ F&O lots

def _parse_fno_lots(payload: bytes) -> list[dict]:
    rows = list(csv.reader(io.StringIO(payload.decode("utf-8", "replace"))))
    hdr = [h.strip().upper() for h in rows[0]]
    i_sym = hdr.index("SYMBOL") if "SYMBOL" in hdr else 0
    i_lots = (hdr.index("CANDIDATE_MARKET_LOT") if "CANDIDATE_MARKET_LOT" in hdr
              else hdr.index("MARKET LOT") if "MARKET LOT" in hdr else 2)
    i_sao = hdr.index("SAO_LIST") if "SAO_LIST" in hdr else -1
    today = date.today()
    out = []
    for row in rows[1:]:
        if len(row) <= i_sym or not row[i_sym].strip():
            continue
        try:
            lot = int(float(row[i_lots].strip())) if row[i_lots].strip() else None
        except ValueError:
            lot = None
        out.append({
            "symbol": row[i_sym].strip(),
            "lot_size": lot,
            "sao": (row[i_sao].strip() or None) if 0 <= i_sao < len(row) else None,
            "as_of": today,
        })
    return out


def sync_fno_lots(con) -> dict:
    ep = endpoints()["sources"]["nse_fno_lots"]
    r = http.fetch(ep["url"], source="nse", save_name="fo_mktlots.csv")
    if not r.ok():
        return {"status": "fail", "message": f"fo_mktlots {r.error}"}
    res = _sync_fno_lots_rows(con, _parse_fno_lots(r.bytes))
    _mark_bytes(con, "NSE", ep["url"], r.bytes, res.get("rows", 0), str(r.saved_path))
    return res


def sync_fno_lots_from_bytes(con, payload: bytes) -> dict:
    res = _sync_fno_lots_rows(con, _parse_fno_lots(payload))
    _mark_bytes(con, "NSE", "(manual fo_mktlots.csv)", payload, res.get("rows", 0), None)
    return res


def _sync_fno_lots_rows(con, rows: list[dict]) -> dict:
    n = db.upsert_rows(con, "ref_fno_lot", rows, keys=["symbol", "as_of"])
    symbols = list({x["symbol"] for x in rows})
    if symbols:
        con.execute(
            "UPDATE ref_security SET fno_eligible = TRUE WHERE nse_symbol IN "
            "(SELECT UNNEST(?))", [symbols],
        )
    return {"status": "ok", "rows": n, "fno_symbols": len(symbols)}


# ------------------------------------------------------------------ index constituents

def _parse_index_list(payload: bytes) -> list[dict]:
    rows = list(csv.reader(io.StringIO(payload.decode("utf-8", "replace"))))
    hdr = [h.strip() for h in rows[0]]

    def find(name, default):
        return hdr.index(name) if name in hdr else default

    i_c, i_i, i_s = find("Company Name", 0), find("Industry", 1), find("Symbol", 2)
    i_se, i_isin = find("Series", 3), find("ISIN Code", 4)
    out = []
    for row in rows[1:]:
        if len(row) <= max(i_c, i_i, i_s, i_isin):
            continue
        sym = row[i_s].strip()
        if not sym:
            continue
        out.append({
            "symbol": sym,
            "company": row[i_c].strip(),
            "industry": row[i_i].strip() if i_i < len(row) else None,
            "isin": row[i_isin].strip() if i_isin < len(row) and row[i_isin].strip() else None,
            "series": row[i_se].strip() if i_se < len(row) else None,
        })
    return out


INDEX_SLUGS = [
    "nifty50", "niftynext50", "nifty100", "nifty200", "nifty500",
    "niftymidcap100", "niftymidcap150", "niftysmallcap100", "niftysmallcap250",
]


def sync_index_constituents(con, slugs: list[str] | None = None) -> dict:
    results = {}
    slugs = slugs or INDEX_SLUGS
    ep = endpoints()["sources"]["nse_index_constituents"]
    base = ep["url_pattern"]
    mirror_base = ep.get("mirror_url_pattern", "https://www.niftyindices.com/IndexConstituent/ind_{slug}list.csv")
    for slug in slugs:
        url = base.format(slug=slug)
        r = http.fetch(url, source="nse-indices", save_name=f"ind_{slug}list.csv")
        if not r.ok() and mirror_base:
            m_url = mirror_base.format(slug=slug)
            r = http.fetch(m_url, source="nse-indices", save_name=f"ind_{slug}list.csv")
            url = m_url
        if not r.ok():
            results[slug] = {"status": "skip", "message": r.error}
            continue
        parsed = _parse_index_list(r.bytes)
        today = date.today()
        rows = [dict(x, index_name=slug.upper(), as_of=today) for x in parsed]
        n = db.upsert_rows(con, "ref_index_constituent", rows, keys=["index_name", "symbol", "as_of"])
        _mark_bytes(con, "NSE-INDICES", url, r.bytes, n, str(r.saved_path))
        results[slug] = {"status": "ok", "rows": n}
    return results


def sync_total_market_industries_from_bytes(con, payload: bytes, url: str = "(niftytotalmarket csv)") -> dict:
    """Propagates official NSE Industry labels from Nifty Total Market (~750 equities) into ref_security."""
    from ingest.master_enrichment import classify_security_industries

    parsed = _parse_index_list(payload)
    pairs = [(x["symbol"], x["industry"]) for x in parsed if x.get("symbol") and x.get("industry")]
    res = classify_security_industries(con, pairs, key_col="nse_symbol", overwrite=True)
    _mark_bytes(con, "NSE-INDICES", url, payload, res.get("updated", 0), None)
    return {"status": "ok", "parsed": len(parsed), **res}


def sync_total_market_industries(con) -> dict:
    """Fetches ind_niftytotalmarket_list.csv (750 equities) via official niftyindices.com (nsearchives fallback)."""
    ep = endpoints()["sources"].get("nse_total_market_industries") or {}
    mirror = ep.get("mirror_url", "https://www.niftyindices.com/IndexConstituent/ind_niftytotalmarket_list.csv")
    primary = ep.get("url", "https://nsearchives.nseindia.com/content/indices/ind_niftytotalmarket_list.csv")
    url = mirror
    r = http.fetch(mirror, source="nse-indices", save_name="ind_niftytotalmarket_list.csv")
    if not r.ok() and primary:
        r = http.fetch(primary, source="nse-indices", save_name="ind_niftytotalmarket_list.csv")
        url = primary
    if not r.ok():
        return {"status": "skip", "message": r.error or "fetch failed"}
    return sync_total_market_industries_from_bytes(con, r.bytes, url=url)


def sync_index_list_from_bytes(con, payload: bytes, filename_hint: str = "") -> dict:
    import re as _re
    parsed = _parse_index_list(payload)
    slug_guess = "NIFTY_LIST"
    m = _re.search(r"ind_([a-z0-9]+)list", filename_hint, _re.I)
    if m:
        slug_guess = m.group(1).upper()
    elif not parsed:
        slug_guess = "UNKNOWN"
    today = date.today()
    rows_d = [dict(x, index_name=slug_guess, as_of=today) for x in parsed]
    n = db.upsert_rows(con, "ref_index_constituent", rows_d, keys=["index_name", "symbol", "as_of"])
    _mark_bytes(con, "NSE-INDICES", f"(manual index list: {slug_guess})", payload, n, None)
    return {"status": "ok", "rows": n, "index_name": slug_guess}


# ------------------------------------------------------------------ corporate actions (session API)

def sync_corporate_actions(con, days_back: int = 45, days_fwd: int = 10) -> dict:
    s = bootstrap_nse_session()
    frm = (date.today() - timedelta(days=days_back)).strftime(_API_DATE_FMT)
    to_ = (date.today() + timedelta(days=days_fwd)).strftime(_API_DATE_FMT)
    url = (endpoints()["sources"]["nse_api_session"]["base"]
           + "/api/corporates-corporateActions?index=equities"
           + f"&from_date={frm}&to_date={to_}")
    data = fetch_json(url, source="nse-api", session=s)
    if not data:
        return {"status": "fail", "message": "corporateActions API returned no JSON (see DATA_SOURCES.md session notes)"}
    rows = _parse_corp_actions(data)
    n = db.upsert_rows(con, "corp_action", rows, keys=["symbol", "ex_date", "purpose"])
    return {"status": "ok", "rows": n}


def sync_corporate_actions_from_bytes(con, payload: bytes) -> dict:
    import json
    rows = _parse_corp_actions(json.loads(payload.decode("utf-8", "replace")))
    n = db.upsert_rows(con, "corp_action", rows, keys=["symbol", "ex_date", "purpose"])
    _mark_bytes(con, "NSE-API", "(manual corp actions JSON)", payload, n, None)
    return {"status": "ok", "rows": n}


def _parse_corp_actions(data) -> list[dict]:
    out = []
    for it in data if isinstance(data, list) else []:
        ex = _api_date(it.get("exDate"))
        if ex is None or not (it.get("symbol") or "").strip():
            continue
        out.append({
            "symbol": (it.get("symbol") or "").strip(),
            "isin": it.get("isin") or None,
            "company": it.get("comp") or None,
            "ex_date": ex,
            "record_date": _api_date(it.get("recDate")),
            "purpose": (it.get("purpose") or "").strip(),
            "face_value": _maybe_float(it.get("faceVal")),
            "broadcast_date": _api_date(it.get("caBroadcastDate")),
        })
    return out


def _api_date(v):
    if not v:
        return None
    v = str(v).split()[0]
    for fmt in ("%d-%b-%Y", "%d-%m-%Y"):
        try:
            return datetime.strptime(v, fmt).date()
        except ValueError:
            continue
    return None


def _maybe_float(v):
    try:
        return float(str(v).replace(",", ""))
    except (TypeError, ValueError):
        return None


# ------------------------------------------------------------------ NSE Daily PR Archive (MCAP Shares + Nifty 50 Index Close)

def _parse_nse_mcap_csv(payload: bytes, fallback_date: date | None = None) -> list[dict]:
    """Parses official NSE mcap{ddmmyyyy}.csv returning symbol, series, face_value, shares_outstanding, trade_date."""
    rows = list(csv.reader(io.StringIO(payload.decode("utf-8", "replace"))))
    if not rows:
        return []
    hdr = [h.strip().upper() for h in rows[0]]

    def find_col(prefix: str, default: int | None = None) -> int | None:
        for idx, col in enumerate(hdr):
            if col.startswith(prefix):
                return idx
        return default

    i_dt = find_col("TRADE DATE", 0)
    i_sym = find_col("SYMBOL", 1)
    i_ser = find_col("SERIES", 2)
    i_fv = find_col("FACE VALUE", 6)
    i_iss = find_col("ISSUE SIZE", 7)
    if i_sym is None or i_iss is None:
        return []

    out = []
    for row in rows[1:]:
        if len(row) <= max(i_sym, i_iss):
            continue
        sym = row[i_sym].strip().upper()
        if not sym:
            continue
        raw_sh = _maybe_float(row[i_iss])
        sh = int(round(raw_sh)) if raw_sh and raw_sh > 0 else None
        if not sh:
            continue
        ser = row[i_ser].strip().upper() if i_ser is not None and i_ser < len(row) else "EQ"
        fv = _maybe_float(row[i_fv]) if i_fv is not None and i_fv < len(row) else None
        td = None
        if i_dt is not None and i_dt < len(row) and row[i_dt].strip():
            s_dt = row[i_dt].strip()
            for fmt in ("%d %b %Y", "%d-%b-%Y", "%Y-%m-%d", "%d/%m/%Y"):
                try:
                    td = datetime.strptime(s_dt, fmt).date()
                    break
                except ValueError:
                    continue
        out.append({
            "symbol": sym,
            "series": ser,
            "face_value": fv,
            "shares_outstanding": sh,
            "trade_date": td or fallback_date,
        })
    return out


def _parse_pd_nifty50_row(payload: bytes, d: date) -> dict | None:
    """Extracts official Nifty 50 close OHLC row from pd{ddmmyyyy}.csv inside PR{ddmmyy}.zip."""
    rows = list(csv.reader(io.StringIO(payload.decode("utf-8", "replace"))))
    if not rows:
        return None
    hdr = [h.strip().upper() for h in rows[0]]
    if "SECURITY" not in hdr or "CLOSE_PRICE" not in hdr:
        return None
    i_sec = hdr.index("SECURITY")
    for row in rows[1:]:
        if len(row) <= i_sec or row[i_sec].strip().upper() != "NIFTY 50":
            continue
        def _col(name: str):
            return _maybe_float(row[hdr.index(name)]) if name in hdr and hdr.index(name) < len(row) else None
        close = _col("CLOSE_PRICE")
        if not close:
            return None
        return {
            "source": "NSE-INDEX",
            "date": d,
            "symbol": "NIFTY50",
            "isin": None,
            "series": "IDX",
            "open": _col("OPEN_PRICE"),
            "high": _col("HIGH_PRICE"),
            "low": _col("LOW_PRICE"),
            "close": close,
            "prev_close": _col("PREV_CL_PR"),
            "last": close,
            "volume": int(round(_col("NET_TRDQTY") or 0)),
            "turnover_rs": _col("NET_TRDVAL"),
            "wap": None,
            "trades": int(round(_col("TRADES") or 0)) if _col("TRADES") is not None else None,
        }
    return None


def sync_nse_mcap_csv_bytes(con, payload: bytes, d: date | None = None, url: str = "(manual mcap.csv)") -> dict:
    parsed = _parse_nse_mcap_csv(payload, fallback_date=d)
    if not parsed:
        return {"status": "skip", "rows": 0, "message": "no shares rows in mcap csv"}
    # Prefer EQ/SM/BE series updates without overriding primary shares with obscure series if duplicate symbol exists
    by_sym: dict[str, dict] = {}
    prio = {"EQ": 0, "SM": 1, "BE": 2, "BZ": 3}
    for r in parsed:
        cur = by_sym.get(r["symbol"])
        if cur is None or prio.get(r["series"], 9) < prio.get(cur["series"], 9):
            by_sym[r["symbol"]] = r

    updates = [
        (r["shares_outstanding"], "NSE PR MCAP", r["trade_date"], r["face_value"], r["symbol"])
        for r in by_sym.values()
    ]
    con.executemany(
        """
        UPDATE ref_security
        SET shares_outstanding = ?,
            shares_source = ?,
            shares_as_of = ?,
            face_value = COALESCE(face_value, ?),
            updated_at = current_timestamp
        WHERE nse_symbol = ?
        """,
        updates,
    )
    _mark_bytes(con, "NSE-PR", url, payload, len(updates), None if url.startswith("(") else url)
    return {"status": "ok", "rows": len(updates), "date": str(d or parsed[0]["trade_date"])}


def sync_nse_pr_mcap_from_zip_bytes(con, payload: bytes, d: date, url: str = "(PR.zip)") -> dict:
    import zipfile
    updated = 0
    nifty_ok = False
    with zipfile.ZipFile(io.BytesIO(payload)) as z:
        for name in z.namelist():
            low = name.lower().rsplit("/", 1)[-1]
            if low.startswith("mcap") and low.endswith(".csv"):
                res = sync_nse_mcap_csv_bytes(con, z.read(name), d=d, url=url)
                updated += int(res.get("rows", 0))
            elif low.startswith("pd") and low.endswith(".csv"):
                n_row = _parse_pd_nifty50_row(z.read(name), d)
                if n_row:
                    db.upsert_rows(con, "px_daily", [n_row], keys=["source", "symbol", "date", "series"])
                    nifty_ok = True
    return {"status": "ok" if updated > 0 else "skip", "rows": updated, "nifty50_synced": nifty_ok, "date": str(d)}


def sync_nse_pr_mcap(con, d: date | None = None, lookback_days: int = 7) -> dict:
    """Fetches NSE PR{ddmmyy}.zip (bulk shares_outstanding via mcap CSV + Nifty50 close via pd CSV)."""
    from app.config import data_path
    ep = endpoints()["sources"].get("nse_pr_mcap") or {}
    pattern = ep.get("url_pattern", "https://nsearchives.nseindia.com/archives/equities/bhavcopy/pr/PR{ddmmyy}.zip")
    start_d = d or (date.today() - timedelta(days=1))
    raw_dir = data_path(settings()["data"]["raw_dir"]) / "nse"
    for i in range(max(1, lookback_days) + 1):
        cand = start_d - timedelta(days=i)
        stamp = cand.strftime("%d%m%y")
        # Cache-first check before network call
        if raw_dir.exists():
            cached = sorted(raw_dir.glob(f"PR{stamp}*.zip"))
            if cached:
                res = sync_nse_pr_mcap_from_zip_bytes(con, cached[-1].read_bytes(), cand, url=str(cached[-1]))
                res["raw"] = str(cached[-1])
                res["from_cache"] = True
                return res
        url = pattern.format(ddmmyy=stamp)
        r = http.fetch(url, source="nse", save_name=f"PR{stamp}.zip")
        if r.blocked():
            return {"status": "blocked", "date": str(cand), "message": f"blocked ({r.error}); drop PRddmmyy.zip into data/inbox/"}
        if not r.ok():
            continue
        res = sync_nse_pr_mcap_from_zip_bytes(con, r.bytes, cand, url=url)
        res["raw"] = str(r.saved_path)
        return res
    return {"status": "skip", "message": "no PR zip found within lookback window"}
